5: import { BillStatus, type MappedBill } from '../types';
6: import styles from './bill-action-menu.scss';
7: 
8: type BillActionMenuProps = {
9:   bill: MappedBill;
10:   patientUuid: string;
11:   onMutate?: () => void;
12: };
13: 
14: const BillActionMenu: React.FC<BillActionMenuProps> = ({ bill, patientUuid, onMutate }) => {
15:   const { t } = useTranslation();
16:   const layout = useLayoutType();
17:   const isPending = bill?.status === BillStatus.PENDING;
18: 
